&lt;li style=&quot;font-weight: 400;&quot;&gt;&lt;a href=&quot;https://about.gitlab.com/handbook/paid-time-off/&quot;&gt;&lt;span style=&quot;font-weight: 400;&quot;&gt;Flexible Paid Time Off&lt;/span&gt;&lt;/a&gt;&lt;/li&gt;
&lt;li style=&quot;font-weight: 400;&quot;&gt;&lt;a href=&quot;https://about.gitlab.com/company/culture/inclusion/erg-guide/#:~:text=Definition%20of%20the%20TMRG%20%2D%20Team%20Member%20Resource%20Groups,-TMRGs%20are%20voluntary&amp;amp;text=The%20purpose%20for%20this%20type,developing%20the%20sense%20of%20belonging.&quot;&gt;&lt;span style=&quot;font-weight: 400;&quot;&gt;Team Member Resource Groups&lt;/span&gt;&lt;/a&gt;&lt;/li&gt;
&lt;li style=&quot;font-weight: 400;&quot;&gt;&lt;a href=&quot;https://about.gitlab.com/handbook/stock-options/&quot;&gt;&lt;span style=&quot;font-weight: 400;&quot;&gt;Equity Compensation &amp;amp; Employee Stock Purchase Plan&lt;/span&gt;&lt;/a&gt;&lt;/li&gt;
