&lt;h3 class=&quot;&quot; data-path-to-node=&quot;2&quot;&gt;&lt;strong data-path-to-node=&quot;2&quot; data-index-in-node=&quot;0&quot;&gt;Equity&lt;/strong&gt;&lt;/h3&gt;
